from typing import Type, Callable
from rclpy.node import Node as ROS2BaseNode
from ..logger.logger import logger


class ROS2Subscriber:
    def __init__(
        self,
        node: ROS2BaseNode,
        msg_type: Type,
        topic: str,
        callback: Callable,
        qos_profile: int = 10,
        **kwargs
    ):
        """
        创建ROS2订阅者

        Args:
            node: ROS2BaseNode实例
            msg_type: 消息类型
            topic: 话题名称
            callback: 回调函数
            qos_profile: QoS配置
            **kwargs: 其他参数传递给create_subscription
        """
        self._node = node
        self._msg_type = msg_type
        self._topic = topic
        self._callback = callback
        self._subscription = node.create_subscription(
            msg_type, topic, callback, qos_profile, **kwargs
        )

    @property
    def topic(self) -> str:
        """获取话题名称"""
        return self._topic

    @property
    def msg_type(self) -> Type:
        """获取消息类型"""
        return self._msg_type

    def destroy(self):
        """销毁订阅者"""
        self._node.destroy_subscription(self._subscription)
